#!/usr/bin/env bash
# Owner direction (2026-10-25): backgrounds are FLAT 2D (paper-cut / flat vector),
# limited indigo-violet-teal palette, no glow, no orange/yellow light, no 3D look.
# Regenerates chapter backdrops, ground textures, edge strips, title key art and map.
cd "$(dirname "$0")/.."
REF=art_src/env/c1_far.png
FLAT="Art style: FLAT 2D illustration exactly like the reference image (hand-made 2D animated film background, paper-cut / flat vector look): bold flat colour shapes, crisp clean silhouettes, layered planes, LIMITED palette of deep indigo, violet, dusty teal and a little muted crimson, subtle paper grain. Strictly NO realistic lighting, NO glow, NO bloom, NO light rays, NO orange or yellow lighting, NO fire glow, NO 3D rendering, NO photorealism, NO airbrushed gradients. No text."
gen() { python -I tools/gen_image.py "$1" "$2 $FLAT" --ref $REF "${@:3}" || echo "FAILED $1"; }
gen art_src/env/c1_mid.png "Mid-ground parallax layer for a side-scrolling platformer, chapter 'The Ash Pits': a continuous band of burned village huts, broken temple pillars and leafless banyan trees with hanging roots, as flat dark violet silhouettes with a thin lighter rim, along the BOTTOM half of the image. Everything above the band is plain flat pure green (#00FF00) for chroma keying, with nothing floating in it. The band's bottom edge reaches the bottom of the image. Seamless horizontally. No characters." --aspect 21:9 --size 2K
gen art_src/env/marsh_far.png "Wide panoramic far background for a side-scrolling platformer, chapter 'Mirror Marsh': a still mirror-like marsh at night with flat reflections, drowned Indian temple spires and half-sunken stone elephant statues as flat layered silhouettes, flat bands of teal mist, a pale flat moon, distant violet mountains. The bottom third is a flat dark misty band. Seamless horizontally. No characters." --aspect 21:9 --size 2K
gen art_src/env/marsh_mid.png "Mid-ground parallax layer for a side-scrolling platformer, chapter 'Mirror Marsh': a continuous band of twisted mangrove trees with hanging moss, tall reeds, crooked lantern posts with small pale teal lights, broken carved stone arches, as flat dark teal-violet silhouettes along the BOTTOM half of the image. Everything above the band is plain flat pure magenta (#FF00FF), nothing floating in it. The band's bottom edge reaches the bottom of the image. Seamless horizontally. No characters." --aspect 21:9 --size 2K
gen art_src/env/palace_far.png "Wide panoramic far background for a side-scrolling platformer, chapter 'The Palace Walls': an ancient Indian fortress-palace on a cliff at night (onion domes, chhatri pavilions, tiered towers) as flat layered dark violet silhouettes, small pale-teal window dots (not orange), flat stylised curls of black smoke, a stormy violet sky with a few flat zig-zag lightning shapes in pale lavender. The bottom third is a flat dark band. Seamless horizontally. No characters." --aspect 21:9 --size 2K
gen art_src/env/palace_mid.png "Mid-ground parallax layer for a side-scrolling platformer, chapter 'The Palace Walls': a continuous band of fortified Indian palace battlements, crenellated walls, carved gateways, hanging chains and tattered crimson banners, as flat dark violet-black silhouettes with thin muted gold edges, along the BOTTOM half of the image. Everything above the band is plain flat pure green (#00FF00), with nothing floating in it. The band's bottom edge reaches the bottom of the image. Seamless horizontally. No characters." --aspect 21:9 --size 2K
gen art_src/env/c1_rock.png "Seamless tileable square texture for game ground: flat 2D stylised layered ash rock strata in dark indigo-grey tones with a few flat muted crimson crack lines and tiny copper flecks. Tiles perfectly on all four sides. Flat front view." --aspect 1:1 --size 1K
gen art_src/env/marsh_rock.png "Seamless tileable square texture for game ground: flat 2D stylised packed marsh mud and dark teal stones with thin roots and a few tiny pale teal dots. Tiles perfectly on all four sides. Flat front view." --aspect 1:1 --size 1K
gen art_src/env/palace_rock.png "Seamless tileable square texture for game ground: flat 2D stylised fitted dark violet palace masonry blocks with thin muted gold inlay lines. Tiles perfectly on all four sides. Flat front view." --aspect 1:1 --size 1K
gen art_src/env/c1_edge.png "A single long thin horizontal strip of platform-top edge for a 2D side-scrolling game, seen exactly from the side: a flat stylised crust of grey-violet ash and dark stones with a few dry grass tufts on top and small rocks hanging below. One thin band across the middle, seamless horizontally. Everything else plain flat pure magenta (#FF00FF)." --aspect 21:9 --size 2K
gen art_src/env/marsh_edge.png "A single long thin horizontal strip of platform-top edge for a 2D side-scrolling game, seen exactly from the side: flat stylised dark teal moss and marsh grass with a few tiny pale flowers and roots hanging below. One thin band across the middle, seamless horizontally. Everything else plain flat pure magenta (#FF00FF)." --aspect 21:9 --size 2K
gen art_src/env/palace_edge.png "A single long thin horizontal strip of platform-top edge for a 2D side-scrolling game, seen exactly from the side: a flat stylised dark violet stone cornice with one thin muted gold band and small brackets under it. One single band across the middle, seamless horizontally. Everything else plain flat pure green (#00FF00)." --aspect 21:9 --size 2K
python -I tools/gen_image.py art_src/ui/menu_keyart.png "Title screen key art for a mobile platformer: the boy hero from the second reference image, small in the lower-left third on a cliff edge, seen from behind, red sash and hair blowing, staff on his back, looking across a valley of flat misty layers toward an ancient Indian fortress-palace (onion domes, chhatris, tiered towers) on a far mountain wrapped in flat stylised curls of black smoke, under a big pale flat moon. Keep the upper middle sky calm and empty for a title. The hero keeps his look but is drawn to sit naturally in the flat 2D scene. $FLAT" --ref $REF --ref art_src/chars/hero_ref2.png --aspect 16:9 --size 2K || echo FAILED keyart
gen art_src/ui/journey_map.png "Illustrated journey map for a game's level select, wide panorama from a high three-quarter bird's-eye view: far left a burned Indian village in a valley of ash pits, middle a misty marsh with half-drowned temple spires, far right an ancient Indian fortress-palace (onion domes, chhatris) on a cliff wrapped in flat smoke curls. One clear winding pale path runs from the village on the left, through the marsh, to the palace gate on the right. No markers or circles on the path." --aspect 21:9 --size 2K
echo flat env done
